import { Clock3, FileClock, ShieldCheck, XCircle } from 'lucide-react';

import { AdminMetric, AdminPage, AdminPageHeader, AdminPanel, AdminEmptyState } from '@/features/admin/components';
import { getVendorAccess } from '@/features/vendor/auth/vendorAccess';
import { prisma } from '@/lib/prisma';

export default async function VendorSubmissionsPage(){const access=await getVendorAccess();if(!access.permissions.has('submission:view'))throw new Error('Submission access is required.');const requests=await prisma.adminApprovalRequest.findMany({where:{workspaceId:access.workspace.id,requestedById:access.session.user.id},include:{reviewedBy:{select:{name:true}}},orderBy:{createdAt:'desc'},take:100});return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow="Moderation history" title="Submissions" description="Track the review state of products, collections, promotions, Stories and Reels submitted by your account."/><section className="grid gap-3 sm:grid-cols-3"><AdminMetric icon={Clock3} label="Pending" value={requests.filter(item=>item.status==='PENDING').length}/><AdminMetric icon={ShieldCheck} label="Approved or executed" value={requests.filter(item=>['APPROVED','EXECUTED'].includes(item.status)).length}/><AdminMetric icon={XCircle} label="Rejected" value={requests.filter(item=>item.status==='REJECTED').length}/></section><AdminPanel title="Submission timeline">{requests.length?<div className="space-y-3">{requests.map(request=><article key={request.id} className="rounded-3xl border border-border/60 bg-background/55 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-primary/70">{request.targetType.replaceAll('_',' ')} · {request.action.replaceAll('_',' ')}</p><p className="mt-1 text-sm font-black">{request.reason}</p></div><span className="rounded-full bg-muted px-3 py-1 text-[9px] font-black">{request.status}</span></div><p className="mt-3 text-[10px] text-muted-foreground">Submitted {request.createdAt.toLocaleString('en-NG')}{request.reviewedBy?` · Reviewed by ${request.reviewedBy.name}`:''}</p>{request.reviewNote?<p className="mt-3 rounded-2xl bg-muted/60 p-3 text-xs leading-5">{request.reviewNote}</p>:null}</article>)}</div>:<AdminEmptyState icon={FileClock} title="No submissions yet" description="Items submitted from Vendor Studio will appear here."/>}</AdminPanel></div></AdminPage>}
